// Le no Dify as conversas da Liss que ja foram ENCERRADAS e ainda nao entraram em relatorio.
// Encerrada = a Liss encerrou ([ENCERRAR]) OU o cliente tocou em "Encerrar atendimento" OU 24h sem mensagem do cliente.
const H0 = this.helpers;
const BASE = 'https://atendimento.netliss.com', APP = '845ea1e5-1514-4185-ba04-aaad318d36c4';
const seg = n => { const i = $('Segredos').all().find(x => x.json.chave === n); return i ? String(i.json.valor || '') : ''; };
const tabela = $('Conversas ja marcadas').all().map(i => i.json).filter(r => r && r.conversa);
const marca = {}; for (const r of tabela) marca[r.conversa] = r;
const req = async (o) => H0.httpRequest(Object.assign({ json: true, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true }, o));
// 1) entra no Dify (aceita token no corpo ou nos cookies, conforme a versao)
let hdr = {};
for (const senha of [seg('dify_senha'), Buffer.from(seg('dify_senha')).toString('base64')]) {
  const r = await req({ method: 'POST', url: BASE + '/console/api/login', body: { email: seg('dify_usuario'), password: senha, remember_me: true }, headers: { 'Content-Type': 'application/json' } });
  let sc = r.headers['set-cookie'] || []; if (!Array.isArray(sc)) sc = [sc];
  const ck = sc.map(c => String(c).split(';')[0]);
  const tok = r.body && r.body.data && (r.body.data.access_token || (typeof r.body.data === 'string' ? r.body.data : ''));
  const csrf = (ck.find(c => /csrf_token=/.test(c)) || '').split('=').slice(1).join('=');
  if (r.statusCode < 300 && (tok || ck.length)) { hdr = Object.assign({}, tok ? { Authorization: 'Bearer ' + tok } : {}, ck.length ? { Cookie: ck.join('; ') } : {}, csrf ? { 'X-CSRF-Token': decodeURIComponent(csrf) } : {}); break; }
}
if (!Object.keys(hdr).length) return [{ json: { erro: 'nao consegui entrar no Dify com o usuario e a senha da tabela segredos', conversas: [] } }];
// 2) lista as conversas dos ultimos 04 dias
const limite = Date.now() - 4 * 86400000; const convs = [];
for (let pg = 1; pg <= 10; pg++) {
  const r = await req({ method: 'GET', url: BASE + '/console/api/apps/' + APP + '/chat-conversations?page=' + pg + '&limit=100&sort_by=-updated_at', headers: hdr });
  const d = (r.body && r.body.data) || []; if (r.statusCode >= 300) return [{ json: { erro: 'Dify recusou a lista de conversas (' + r.statusCode + ')', conversas: [] } }];
  let parar = false;
  for (const c of d) { const u = (c.updated_at || c.created_at) * 1000; if (u < limite) { parar = true; break; } convs.push(c); }
  if (parar || !r.body.has_more) break;
}
// 3) para cada conversa ainda nao relatada: le as mensagens e ve se encerrou
const limpa = s => String(s || '').replace(/\[(PIX|LINKCARTAO|PEDIDO)\][\s\S]*?\[\/\1\]/g, '[$1]').replace(/\[ACAO:[A-Z_]+\]/g, '').replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[a-z]+/g, '[e-mail]').trim();
const out = []; const agora = Date.now();
for (const c of convs) {
  const m0 = marca[c.id]; if (m0 && m0.relatada_em) continue;
  const r = await req({ method: 'GET', url: BASE + '/console/api/apps/' + APP + '/chat-messages?conversation_id=' + c.id + '&limit=100', headers: hdr });
  const ms = ((r.body && r.body.data) || []).sort((a, b) => a.created_at - b.created_at);
  if (!ms.length) continue;
  const ultima = ms[ms.length - 1]; const ult = ultima.created_at * 1000;
  let por = '';
  if (/\[ENCERRAR\]/.test(ultima.answer || '')) por = 'a Liss encerrou';
  else if (m0 && m0.encerrada_por) por = m0.encerrada_por;
  else if (agora - ult >= 24 * 3600000) por = '24h sem resposta do cliente';
  if (!por) continue;
  const linhas = []; const ferramentas = [];
  for (const m of ms) {
    linhas.push('CLIENTE: ' + limpa(m.query).slice(0, 500));
    for (const t of (m.agent_thoughts || [])) if (t.tool) { const obs = String(t.observation || ''); ferramentas.push(t.tool); linhas.push('  [sistema: ' + t.tool + ' -> ' + limpa(obs).replace(/\s+/g, ' ').slice(0, 160) + ']'); }
    linhas.push('LISS: ' + limpa(m.answer).replace(/\[ENCERRAR\]/g, '[encerrou]').slice(0, 700));
  }
  out.push({ conversa: c.id, encerrada_por: por, mensagens: ms.length, inicio: new Date(ms[0].created_at * 1000).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }).slice(0, 17),
    ferramentas: [...new Set(ferramentas)], texto: linhas.join('\n').slice(0, 12000) });
}
return [{ json: { erro: '', conversas: out } }];

