const lidas = $('Ler conversas encerradas no Dify').first().json;
const convs = lidas.conversas || []; const ias = $input.all().map(i => i.json);
const p2 = n => String(n).padStart(2, '0');
const ontem = new Date(Date.now() - 86400000).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
if (lidas.erro) return [{ json: { msgs: ['⚠️ RELATÓRIO DA LISS NÃO RODOU\n\n' + lidas.erro], marcar: [] } }];
if (!convs.length) return [{ json: { msgs: ['🤖 RELATÓRIO DA LISS\n\nNenhuma conversa encerrada desde o último relatório.'], marcar: [] } }];
const cont = {}; const blocos = []; let problemas = 0;
const ias2 = convs.length ? ias : []; convs.forEach((c, i) => {
  let a = {}; try { const t = ((ias2[i] || {}).content || []).map(x => x.text || '').join(''); a = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { a = {}; }
  const res = a.resultado || (c.ferramentas.includes('gerar_cobranca') ? 'cobranca gerada' : c.ferramentas.includes('gerar_teste') ? 'teste' : 'sem análise');
  cont[res] = (cont[res] || 0) + 1;
  if (a.problema_liss) problemas++;
  blocos.push(p2(i + 1) + '. ' + (a.cliente || 'cliente') + ' · ' + res.toUpperCase() + ' · ' + c.mensagens + ' msgs · ' + c.inicio
    + '\nQueria: ' + (a.queria || '-') + '\nTerminou: ' + (a.onde_parou || c.encerrada_por) + ' (' + c.encerrada_por + ')'
    + (a.problema_liss ? '\n⚠️ Liss: ' + a.problema_liss : '') + (a.dica ? '\n💡 ' + a.dica : '') + '\nID: ' + c.conversa.slice(0, 8));
});
const topo = '🤖 RELATÓRIO DA LISS (conversas encerradas)\n\nConversas: ' + p2(convs.length) + '\n' + Object.entries(cont).map(([k, v]) => '· ' + k + ': ' + p2(v)).join('\n')
  + '\n⚠️ Com problema da Liss: ' + p2(problemas) + '\n\nPara ver a conversa inteira: Dify > Liss > Registros (procure pelo ID).';
const msgs = [topo]; let atual = '';
for (const b of blocos) { if ((atual + '\n\n' + b).length > 3500) { msgs.push(atual); atual = b; } else atual = atual ? atual + '\n\n' + b : b; }
if (atual) msgs.push(atual);
const quando = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }).slice(0, 17);
return [{ json: { msgs, marcar: convs.map(c => ({ conversa: c.conversa, encerrada_por: c.encerrada_por, relatada_em: quando })) } }];
